package org.novasos.healthysv2.appointment;
import static org.assertj.core.api.Assertions.assertThat;import java.time.Instant;import java.util.UUID;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.ActiveProfiles;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test") @SpringBootTest @Import(TestcontainersConfiguration.class) @Transactional class AppointmentRepositoryIntegrationTests{
 @Autowired AppointmentRepository repository;@Autowired JdbcTemplate jdbc;
 @Test void persistsCompleteAggregate(){UUID patient=patient(),professional=professional(),organization=organization(),participant=person();Instant start=Instant.now().plusSeconds(3600);var a=Appointment.create(patient,professional,organization,null,"CONSULTATION",start,start.plusSeconds(1800),"Follow-up",participant);a.addParticipant(participant,"PATIENT");a.checkIn("Q-TEST",participant);var saved=repository.saveAndFlush(a);var found=repository.findById(saved.getId()).orElseThrow();assertThat(found.getParticipants()).hasSize(1);assertThat(found.getHistory()).hasSize(2);assertThat(found.getQueue()).hasSize(1);assertThat(found.getCreatedAt()).isNotNull();}
 private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Test","User","ACTIVE");return id;}private UUID patient(){UUID id=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",id,person(),"PAT-"+id);return id;}private UUID professional(){UUID id=UUID.randomUUID();jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type) values (?,?,?,?)",id,person(),"PRO-"+id,"DOCTOR");return id;}private UUID organization(){UUID id=UUID.randomUUID();jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",id,"ORG-"+id,"Hospital");return id;}
}
